    for i in range(H):
        for j in range(W):
            c=g[i][j]
            if c and (i,j) not in seen:
                q=[(i,j)]; seen.add((i,j)); cells=[]
                while q:
                    a,b=q.pop(); cells.append((a,b))
                    for da in(-1,0,1):
                        for db in(-1,0,1):
                            p,q2=a+da,b+db
                            if 0<=p<H and 0<=q2<W and g[p][q2]==c and (p,q2) not in seen:
                                seen.add((p,q2)); q.append((p,q2))
                rs=[x[0] for x in cells]; cs=[x[1] for x in cells]
                comps.append({'c':c,'cells':[(r-min(rs),cc-min(cs)) for r,cc in cells],'r0':min(rs),'l0':min(cs)})
    ss=comps
