        # intervals per component along axis, relative to min extent of whole set
        mins=min(cp[axis] for cp in s); maxs=max(cp[axis]+max(cell[1 if axis=='l' else 0] for _,cell in cp['cells']) for cp in s)
        res=[]
        for cp in s:
            lo=(cp['l0']-mins) if axis=='l' else (cp['r0']-mins)
            hi=(cp['l0']+max(cc for _,cc in cp['cells']) - mins) if axis=='l' else (cp['r0']+max(r_ for r_,_ in cp['cells']) - mins)
            res.append((lo,hi,cp['c']))
        return res,int(mins if axis=='l' else mins)
    int_l,int_mins=proj_int(ss,'l'); int_r,_=proj_int(ss,'r')
