    # check overlap properly: normalize each interval to its own start within the min baseline, compare normalized
    horiz = any(int_l[i][1]>int_l[i+1][0] and int_l[i+1][1]>int_l[i][0] for i in range(len(int_l)-1)) or any(int_r[i][1]>int_r[i+1][0] and int_r[i+1][1]>int_r[i][0] for i in range(len(int_r)-1))
    if not horiz:
        out=[[0]*(max(cc for _,cc in max(cp['cells'] for cp in ss))+1) for _ in range(sum(max(r_ for r_,_ in cp['cells'])+1 for cp in ss))]
        r=0
        for cp in ss:
            for ri,cc in cp['cells']: out[r+ri][cc]=cp['c']
            r+=max(r_ for r_,_ in cp['cells'])+1
    else:
        out=[[0]*sum(max(cc for _,cc in cp['cells'])+1 for cp in ss) for _ in range(max(max(r_ for r_,_ in cp['cells'])+1 for cp in ss))]
        c=0
        for cp in ss:
            for ri,cc in cp['cells']: out[ri][c+cc]=cp['c']
            c+=max(cc for _,cc in cp['cells'])+1
    return out
